</style>
</head>
<body>
  <div class="app">
    <div class="card">
      <header>
        <h1>📝 Todo List</h1>
        <div class="input-row">
          <input
            id="todo-input"
            type="text"
            placeholder="What needs to be done?"
            autocomplete="off"
            maxlength="200"
          />
          <button id="add-btn" type="button">Add</button>
        </div>
      </header>

      <div class="toolbar">
        <div class="filters" role="tablist">
          <button class="filter-btn active" data-filter="all" type="button">All</button>
          <button class="filter-btn" data-filter="active" type="button">Active</button>
          <button class="filter-btn" data-filter="completed" type="button">Completed</button>
        </div>
        <span class="count" id="count">0 items</span>
      </div>

      <ul class="todo-list" id="todo-list"></ul>
      <div class="empty" id="empty" style="display:none;">No todos here.</div>

      <footer>
        <span class="hint">Stored locally in your browser</span>
        <button id="clear-completed" type="button">Clear completed</button>
      </footer>
    </div>
  </div>

<script>
(function () {
  "use strict";

  const STORAGE_KEY = "todo_app_items_v1";
  const FILTER_KEY = "todo_app_filter_v1";

  /** @type {{id:string,text:string,completed:boolean,createdAt:number}[]} */
  let todos = loadTodos();
  let filter = loadFilter();

  const inputEl = document.getElementById("todo-input");
  const addBtn = document.getElementById("add-btn");
  const listEl = document.getElementById("todo-list");
  const emptyEl = document.getElementById("empty");
  const countEl = document.getElementById("count");
  const filterEls = document.querySelectorAll(".filter-btn");
  const clearBtn = document.getElementById("clear-completed");

  // --- Persistence ---------------------------------------------------------
  function loadTodos() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(
        (t) => t && typeof t.id === "string" && typeof t.text === "string" && typeof t.completed === "boolean"
      );
    } catch (e) {
      console.warn("Failed to load todos:", e);
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      console.warn("Failed to save todos:", e);
    }
  }

  function loadFilter() {
    const f = localStorage.getItem(FILTER_KEY);
    return f === "active" || f === "completed" ? f : "all";
  }

  function saveFilter() {
    try {
      localStorage.setItem(FILTER_KEY, filter);
    } catch (e) {
      console.warn("Failed to save filter:", e);
    }
  }

  // --- Helpers -------------------------------------------------------------
  function makeId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function getFilteredTodos() {
    if (filter === "active") return todos.filter((t) => !t.completed);
    if (filter === "completed") return todos.filter((t) => t.completed);
    return todos;
  }

  // --- Rendering -----------------------------------------------------------
  function render() {
    const visible = getFilteredTodos();

    // Filter buttons
    filterEls.forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.filter === filter);
    });

    // List
    listEl.innerHTML = "";
    visible.forEach((todo) => {
      const li = document.createElement("li");
      li.className = "todo-item" + (todo.completed ? " completed" : "");
      li.dataset.id = todo.id;

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.className = "todo-checkbox";
      checkbox.checked = todo.completed;
      checkbox.setAttribute(
        "aria-label",
        todo.completed ? "Mark as active" : "Mark as completed"
      );
      checkbox.addEventListener("change", () => toggleTodo(todo.id));

      const text = document.createElement("span");
      text.className = "todo-text";
      text.textContent = todo.text;

      const del = document.createElement("button");
      del.type = "button";
      del.className = "delete-btn";
      del.textContent = "Delete";
      del.setAttribute("aria-label", "Delete todo");
      del.addEventListener("click", () => deleteTodo(todo.id));

      li.appendChild(checkbox);
      li.appendChild(text);
      li.appendChild(del);
      listEl.appendChild(li);
    });

    // Empty state
    const isEmpty = visible.length === 0;
    emptyEl.style.display = isEmpty ? "block" : "none";
    listEl.style.display = isEmpty ? "none" : "block";

    // Count
    const activeCount = todos.filter((t) => !t.completed).length;
    countEl.textContent =
      activeCount === 1 ? "1 active item" : activeCount + " active items";

    // Clear completed button
    const hasCompleted = todos.some((t) => t.completed);
    clearBtn.disabled = !hasCompleted;
  }

  // --- Actions -------------------------------------------------------------
  function addTodo(text) {
    const trimmed = (text || "").trim();
    if (!trimmed) return;
    todos.push({
      id: makeId(),
      text: trimmed,
      completed: false,
      createdAt: Date.now(),
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    const t = todos.find((x) => x.id === id);
    if (!t) return;
    t.completed = !t.completed;
    saveTodos();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter((x) => x.id !== id);
    saveTodos();
    render();
  }

  function clearCompleted() {
    const before = todos.length;
    todos = todos.filter((t) => !t.completed);
    if (todos.length !== before) {
      saveTodos();
      render();
    }
  }

  function setFilter(next) {
    if (next !== "all" && next !== "active" && next !== "completed") return;
    if (filter === next) return;
    filter = next;
    saveFilter();
    render();
  }

  // --- Events --------------------------------------------------------------
  addBtn.addEventListener("click", () => {
    addTodo(inputEl.value);
    inputEl.value = "";
    inputEl.focus();
  });

  inputEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      addTodo(inputEl.value);
      inputEl.value = "";
    }
  });

  filterEls.forEach((btn) => {
    btn.addEventListener("click", () => setFilter(btn.dataset.filter));
  });

  clearBtn.addEventListener("click", clearCompleted);

  // Initial paint
  render();
  inputEl.focus();
})();
</script>
</body>
</html>
